<?php
declare(strict_types=1);
require_once __DIR__.'/../config.php';
require_once __DIR__.'/db.php';
function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function json_response($data,int $status=200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function request_base(): string { $https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||($_SERVER['SERVER_PORT']??'')==='443'; return ($https?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost'); }
function base_url(): string { return APP_BASE_URL!==''?rtrim(APP_BASE_URL,'/'):request_base(); }
function user_row_to_array(array $r): array {
  $r['id']=(int)$r['id']; $r['password']=(string)$r['password_hash']; $r['isAdmin']=(bool)$r['is_admin']; $r['active']=(bool)$r['active'];
  $r['createdAt']=$r['created_at']; $r['expiresAt']=$r['expires_at']; $r['updateUuid']=$r['update_uuid'];
  $r['passwordResetTokenHash']=$r['password_reset_token_hash']; $r['passwordResetExpiresAt']=$r['password_reset_expires_at'];
  unset($r['is_admin'],$r['created_at'],$r['expires_at'],$r['update_uuid'],$r['password_reset_token_hash'],$r['password_reset_expires_at']);
  return $r;
}
function get_user(string $username): ?array { $st=db()->prepare('SELECT * FROM users WHERE username=? LIMIT 1');$st->execute([$username]);$r=$st->fetch();return $r?user_row_to_array($r):null; }
function find_login(string $login): ?array { $st=db()->prepare('SELECT * FROM users WHERE username=? OR email=? LIMIT 1');$st->execute([trim($login),trim($login)]);$r=$st->fetch();return $r?user_row_to_array($r):null; }
function list_users(): array { $rows=db()->query('SELECT * FROM users ORDER BY id ASC')->fetchAll();return array_map('user_row_to_array',$rows); }
function save_user(array $u): void {
  $username=trim((string)($u['username']??'')); if($username==='')throw new RuntimeException('Usuário inválido.');
  $st=db()->prepare('SELECT id FROM users WHERE username=? LIMIT 1');$st->execute([$username]);$id=$st->fetchColumn();
  $sql=$id ? 'UPDATE users SET email=?,password_hash=?,role=?,is_admin=?,status=?,active=?,plan=?,expires_at=?,update_uuid=?,password_reset_token_hash=?,password_reset_expires_at=?,updated_at=NOW() WHERE id=?' : 'INSERT INTO users(username,email,password_hash,role,is_admin,status,active,plan,expires_at,update_uuid,password_reset_token_hash,password_reset_expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())';
  $vals=[(string)($u['email']??''),(string)($u['password']??''),(is_admin($u)?'admin':'user'),is_admin($u)?1:0,(string)($u['status']??'active'),($u['active']??true)?1:0,(string)($u['plan']??'trial'),$u['expiresAt']??null,$u['updateUuid']??null,$u['passwordResetTokenHash']??null,$u['passwordResetExpiresAt']??null];
  if($id){$vals[]=$id;} else {$vals=array_merge([$username],$vals);} db()->prepare($sql)->execute($vals);
}
function is_admin(?array $u): bool { return $u && (($u['isAdmin']??false)===true || (string)($u['role']??'')==='admin' || strtolower((string)($u['username']??''))==='admin'); }
function current_user(): ?array { return isset($_SESSION['username'])?get_user((string)$_SESSION['username']):null; }
function require_auth(): array { $u=current_user();if(!$u){if(str_starts_with($_SERVER['REQUEST_URI']??'','/api/'))json_response(['error'=>'Não autenticado'],401);header('Location:/login.php');exit;}return $u; }
function csrf_token(): string { if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf']; }
function check_csrf(): void { $v=$_POST['csrf']??($_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!$v||!hash_equals((string)($_SESSION['csrf']??''),(string)$v))json_response(['error'=>'CSRF inválido'],419); }
function default_config(): array { return ['Version'=>1,'VersionName'=>'1','AppVersion'=>1,'UpdateApk'=>'','Actualization'=>'false','UdpPort'=>'7300','Contato'=>'','Site'=>'','Theme'=>['Version'=>'1','AppName'=>'ConnectPlus','ImgFundo'=>'','ImgLogo'=>'','ImgBanner'=>'','ImgMenu'=>'','ImgLogs'=>'','ImgCheck'=>'','ImgUser'=>'','ImgPass'=>'','ImgUpdate'=>'','ImgRouter'=>'','ImgDownload'=>'','ImgUpload'=>'','ColorOne'=>'','ColorTwo'=>'','ColorStarter'=>'','ColorDialogs'=>'','ColorButtons'=>'','Update'=>''],'Servers'=>[],'Sms'=>['Version'=>'1','Update'=>'','Notes'=>'']]; }
function db_config(string $username): array {
  $st=db()->prepare('SELECT * FROM configs WHERE user_id=(SELECT id FROM users WHERE username=?) LIMIT 1');$st->execute([$username]);$c=$st->fetch();
  $out=default_config(); if($c){$out['Version']=(int)$c['version'];$out['VersionName']=(string)$c['version_name'];$out['AppVersion']=(int)$c['app_version'];$out['UpdateApk']=(string)$c['update_apk'];$out['Actualization']=(string)$c['actualization'];$out['UdpPort']=(string)$c['udp_port'];$out['Contato']=(string)$c['contato'];$out['Site']=(string)$c['site'];}
  $st=db()->prepare('SELECT * FROM themes WHERE user_id=(SELECT id FROM users WHERE username=?) LIMIT 1');$st->execute([$username]);if($t=$st->fetch()){foreach(['Version'=>'version','AppName'=>'app_name','ImgFundo'=>'img_fundo','ImgLogo'=>'img_logo','ImgBanner'=>'img_banner','ImgMenu'=>'img_menu','ImgLogs'=>'img_logs','ImgCheck'=>'img_check','ImgUser'=>'img_user','ImgPass'=>'img_pass','ImgUpdate'=>'img_update','ImgRouter'=>'img_router','ImgDownload'=>'img_download','ImgUpload'=>'img_upload','ColorOne'=>'color_one','ColorTwo'=>'color_two','ColorStarter'=>'color_starter','ColorDialogs'=>'color_dialogs','ColorButtons'=>'color_buttons','Update'=>'update_url'] as $k=>$col)$out['Theme'][$k]=(string)$t[$col];}
  $st=db()->prepare('SELECT * FROM sms WHERE user_id=(SELECT id FROM users WHERE username=?) LIMIT 1');$st->execute([$username]);if($x=$st->fetch())$out['Sms']=['Version'=>(string)$x['version'],'Update'=>(string)$x['update_url'],'Notes'=>(string)$x['notes']];
  $st=db()->prepare('SELECT * FROM servers WHERE user_id=(SELECT id FROM users WHERE username=?) ORDER BY id ASC');$st->execute([$username]);$out['Servers']=[];foreach($st as $x){$row=[];foreach(['Name','ColorName','Description','ColorDescription','FLAG','ServerIP','ServerPort','CheckUser','USER','PASS','Payload','ProxyIP','ProxyPort','SNI','Path','TLSVersion','Color','Info'] as $k)$row[$k]=(string)($x[strtolower($k)]??$x[$k]??'');$out['Servers'][]=$row;}
  return normalize_config($out);
}
function user_config(array $u): array { return db_config((string)$u['username']); }
function normalize_config(array $c): array { $d=default_config();$c=array_replace_recursive($d,$c);$c['Version']=(int)($c['Version']?:1);$c['AppVersion']=(int)($c['AppVersion']?:$c['Version']);$c['VersionName']=(string)($c['VersionName']?:$c['Version']);$c['Actualization']=in_array($c['Actualization'],[true,1,'1','true'],true)?'true':'false';$c['UdpPort']=(string)$c['UdpPort'];$c['Contato']=(string)$c['Contato'];$c['Site']=(string)$c['Site'];$c['Servers']=is_array($c['Servers'])?$c['Servers']:[];foreach($c['Servers'] as &$server){if(trim((string)($server['ColorName']??''))==='')$server['ColorName']='#ffffff';if(trim((string)($server['ColorDescription']??''))==='')$server['ColorDescription']='#ffffff';}unset($server);$c['Sms']['Version']=(string)($c['Sms']['Version']??'1');$c['Sms']['Update']=(string)($c['Sms']['Update']??'');$c['Sms']['Notes']=(string)($c['Sms']['Notes']??'');$c['Theme']['Version']=(string)($c['Theme']['Version']??'1');$c['Theme']['AppName']=trim((string)($c['Theme']['AppName']??''));if($c['Theme']['AppName']==='')$c['Theme']['AppName']='ConnectPlus';return $c; }
function stable($v): string { if(is_array($v)){ $assoc=array_keys($v)!==range(0,count($v)-1);if($assoc)ksort($v);return '['.implode(',',array_map('stable',$v)).']';}return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE); }
function apply_versions(array $old,array $new): array { foreach(['config','sms','theme'] as $k){$a=$k==='config'?['UdpPort'=>$old['UdpPort'],'Contato'=>$old['Contato'],'Site'=>$old['Site'],'Servers'=>$old['Servers']]:($k==='sms'?['Update'=>$old['Sms']['Update'],'Notes'=>$old['Sms']['Notes']]:array_diff_key($old['Theme'],['Version'=>1,'Update'=>1]));$b=$k==='config'?['UdpPort'=>$new['UdpPort'],'Contato'=>$new['Contato'],'Site'=>$new['Site'],'Servers'=>$new['Servers']]:($k==='sms'?['Update'=>$new['Sms']['Update'],'Notes'=>$new['Sms']['Notes']]:array_diff_key($new['Theme'],['Version'=>1,'Update'=>1]));$changed=stable($a)!==stable($b);if($k==='config')$new['Version']=$changed?(int)$old['Version']+1:(int)$old['Version'];if($k==='sms')$new['Sms']['Version']=(string)($changed?(int)$old['Sms']['Version']+1:(int)$old['Sms']['Version']);if($k==='theme')$new['Theme']['Version']=(string)($changed?(int)$old['Theme']['Version']+1:(int)$old['Theme']['Version']);}return $new; }
function save_config(array &$u,array $c): void { $c=normalize_config($c);$c['Update']=update_resource((string)$u['username'],'config');$pdo=db();$pdo->beginTransaction();try{$uid=(int)$u['id'];$st=$pdo->prepare('INSERT INTO configs(user_id,version,version_name,app_version,update_apk,actualization,udp_port,contato,site) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE version=VALUES(version),version_name=VALUES(version_name),app_version=VALUES(app_version),update_apk=VALUES(update_apk),actualization=VALUES(actualization),udp_port=VALUES(udp_port),contato=VALUES(contato),site=VALUES(site)');$st->execute([$uid,$c['Version'],$c['VersionName'],$c['AppVersion'],$c['UpdateApk'],$c['Actualization'],$c['UdpPort'],$c['Contato'],$c['Site']]);$pdo->prepare('DELETE FROM servers WHERE user_id=?')->execute([$uid]);$ins=$pdo->prepare('INSERT INTO servers(user_id,name,color_name,description,color_description,flag,server_ip,server_port,check_user,username,password,payload,proxy_ip,proxy_port,sni,path,tls_version,color,info) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($c['Servers'] as $s){$ins->execute([$uid,(string)($s['Name']??''),(string)($s['ColorName']??''),(string)($s['Description']??''),(string)($s['ColorDescription']??''),(string)($s['FLAG']??''),(string)($s['ServerIP']??''),(string)($s['ServerPort']??''),(string)($s['CheckUser']??''),(string)($s['USER']??''),(string)($s['PASS']??''),(string)($s['Payload']??''),(string)($s['ProxyIP']??''),(string)($s['ProxyPort']??''),(string)($s['SNI']??''),(string)($s['Path']??''),(string)($s['TLSVersion']??''),(string)($s['Color']??''),(string)($s['Info']??'')]);}$t=$c['Theme'];$pdo->prepare('INSERT INTO themes(user_id,version,app_name,img_fundo,img_logo,img_banner,img_menu,img_logs,img_check,img_user,img_pass,img_update,img_router,img_download,img_upload,color_one,color_two,color_starter,color_dialogs,color_buttons,update_url) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE version=VALUES(version),app_name=VALUES(app_name),img_fundo=VALUES(img_fundo),img_logo=VALUES(img_logo),img_banner=VALUES(img_banner),img_menu=VALUES(img_menu),img_logs=VALUES(img_logs),img_check=VALUES(img_check),img_user=VALUES(img_user),img_pass=VALUES(img_pass),img_update=VALUES(img_update),img_router=VALUES(img_router),img_download=VALUES(img_download),img_upload=VALUES(img_upload),color_one=VALUES(color_one),color_two=VALUES(color_two),color_starter=VALUES(color_starter),color_dialogs=VALUES(color_dialogs),color_buttons=VALUES(color_buttons),update_url=VALUES(update_url)')->execute([$uid,$t['Version'],$t['AppName'],$t['ImgFundo'],$t['ImgLogo'],$t['ImgBanner'],$t['ImgMenu'],$t['ImgLogs'],$t['ImgCheck'],$t['ImgUser'],$t['ImgPass'],$t['ImgUpdate'],$t['ImgRouter'],$t['ImgDownload'],$t['ImgUpload'],$t['ColorOne'],$t['ColorTwo'],$t['ColorStarter'],$t['ColorDialogs'],$t['ColorButtons'],$t['Update']]);$s=$c['Sms'];$pdo->prepare('INSERT INTO sms(user_id,version,update_url,notes) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE version=VALUES(version),update_url=VALUES(update_url),notes=VALUES(notes)')->execute([$uid,$s['Version'],$s['Update'],$s['Notes']]);$pdo->commit();write_update_files($u,$c);}catch(Throwable $e){$pdo->rollBack();throw $e;} }
function update_user_dir(string $username): string {$safe=preg_replace('/[^a-zA-Z0-9_.-]/','_',$username);return UPDATE_DIR.'/'.$safe;}
function update_resource(string $username,string $resource): string{return base_url().'/update/'.rawurlencode($username).'/'.rawurlencode($resource);}
function write_update_file(string $file,string $json,string $resource): void {$dir=dirname($file);$tmp=$dir.'/.' . basename($file).'.tmp-'.bin2hex(random_bytes(4));if(file_put_contents($tmp,$json."\n",LOCK_EX)===false)throw new RuntimeException('Não foi possível gravar update/'.$resource);if(!rename($tmp,$file)){@unlink($tmp);throw new RuntimeException('Não foi possível publicar update/'.$resource);}}
function write_update_files(array $u,array $c): void {$dir=update_user_dir((string)$u['username']);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Não foi possível criar a pasta de atualização do usuário.');$config=$c;$config['Update']=update_resource((string)$u['username'],'config');$theme=$c['Theme'];$sms=$c['Sms'];$app=['Version'=>(string)$c['AppVersion'],'Update'=>(string)$c['UpdateApk'],'VersionName'=>(string)$c['VersionName'],'UpdateApk'=>(string)$c['UpdateApk'],'Actualization'=>(string)$c['Actualization']];$flags=JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT|JSON_INVALID_UTF8_SUBSTITUTE;foreach(['config'=>$config,'theme'=>$theme,'sms'=>$sms,'appupdate'=>$app] as $name=>$payload){$json=json_encode($payload,$flags);if($json===false)throw new RuntimeException('Não foi possível gerar o JSON de '.$name.'.');write_update_file($dir.'/'.$name,$json,$name);}}
function ensure_uuid(array &$u): string {$x=(string)($u['updateUuid']??'');if(!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i',$x)){$x=uuidv4();$u['updateUuid']=$x;save_user($u);}return strtolower($x);}
function uuidv4(): string {$d=random_bytes(16);$d[6]=chr((ord($d[6])&15)|64);$d[8]=chr((ord($d[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4));}
function uuid_resource(string $uuid,string $resource): string{return base_url().'/u/'.rawurlencode($uuid).'/'.rawurlencode($resource);}
function audit(array $u,string $action,string $module,string $description=''): void {db()->prepare('INSERT INTO logs(user_id,username,action,module,description,created_at) VALUES(?,?,?,?,?,NOW())')->execute([(int)($u['id']??0),(string)($u['username']??''),$action,$module,$description]);}
function cdn_normalize($value): ?string {$v=trim((string)$value);if($v==='')return null;if(!preg_match('~^https?://~i',$v))$v='https://'.$v;$p=parse_url($v);if(!$p||empty($p['host'])||in_array(strtolower($p['host']),['localhost','127.0.0.1','0.0.0.0','::1'],true))return null;return rtrim($v,'/');}
function cdn_list(array $u): array {$st=db()->prepare('SELECT url FROM cdn_pool WHERE user_id=? ORDER BY id');$st->execute([(int)$u['id']]);return array_values(array_filter(array_map('cdn_normalize',$st->fetchAll(PDO::FETCH_COLUMN))));}
function save_cdn(array $u,array $urls): void {$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM cdn_pool WHERE user_id=?')->execute([(int)$u['id']]);$ins=$pdo->prepare('INSERT INTO cdn_pool(user_id,url) VALUES(?,?)');foreach($urls as $url)$ins->execute([(int)$u['id'],$url]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}}
function public_json_config(string $username): array {$u=get_user($username);if(!$u)throw new RuntimeException('Usuário não encontrado');$c=user_config($u);$c['Update']=update_resource($username,'config');return $c;}
